<script id=data type=application/json>DATA</script><script>
'use strict';const cases=JSON.parse(document.getElementById('data').textContent),byId=new Map(cases.map(c=>[c.id,c])),key='gojo-lattice-interiors-ratings-v1';let current=cases[0],mode='cells',ratings={};try{ratings=JSON.parse(localStorage.getItem(key)||'{}')}catch{}const $=id=>document.getElementById(id),esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function review(c){const r=ratings[c.id];return r?.fingerprint===c.fingerprint?r:null}function persist(){try{localStorage.setItem(key,JSON.stringify(ratings))}catch{$('rating-status').textContent='Browser storage unavailable; export your ratings.'}paintRatings()}
function paintRatings(){const r=review(current);$('review-note').value=r?.note||'';document.querySelectorAll('[data-rating]').forEach(b=>b.classList.toggle('active',Number(b.dataset.rating)===(r?.rating||0)));$('rating-status').textContent=r?.rating?'Rated '+r.rating+'/5':'';document.querySelectorAll('.card').forEach(card=>{const r=review(byId.get(card.dataset.case));card.querySelector('.user-rating').textContent=r?.rating?' · '+r.rating+'/5':''})}
function render(){const i=Number($('rung').value),s=current.stages[i];$('title').textContent=current.id+' · '+current.name;$('description').textContent=current.description;$('basis-image').src=current.stages[0].lines;$('stage-title').textContent=s.name;$('field').src=mode==='lines'?s.lines:mode==='removed'?s.removed:s.fill;$('stage-description').textContent=s.description;$('stage-number').textContent=(i+1)+' / '+current.stages.length;$('stage-status').textContent=s.embedded?'Exclusive interiors · closed cells · embedding checked':'Proposal / attention: '+s.blocked+' rejected or conflicting witnesses, '+s.open+' unresolved';$('stage-status').classList.toggle('bad',!s.embedded);$('facts').textContent=s.read.acceptedGroups+' cells from '+s.read.atomicFaces+' actual atomic faces. '+s.read.removedInternalEdges+' internal separators withdrawn. '+s.read.multiplyOwnedAtoms+' multiply owned; '+s.read.unownedAtoms+' unowned; '+s.read.overlappingAtomPairs+' embedded overlap pairs. '+current.sharedInteriorEdges+' shared inter-cell boundary edges in the final field.';
const warnings=s.cells.filter(c=>c.boundaryDetailWarning).length;$('preference').textContent='Authored preference read: '+warnings+' cells have repeated fine same-heading returns. Broad sides collapse straight subdivisions; compactness and short runs depend on the declared basis. A star can alternate turning directions without being edge noise.';$('packet').href=current.id+'.gojo.json.gz';$('cell-facts').innerHTML=s.cells.map(c=>'<tr><td>'+(c.index+1)+'</td><td>'+c.atoms+'</td><td>'+c.sides+'</td><td>'+c.reflexTurns+'</td><td>'+Math.round(c.boxOccupancy*100)+'%</td><td>'+(c.shape?.fineToothReturns??'open')+'</td><td>'+(c.boundaryDetailWarning?'Boundary-detail cue':'Inspect shape')+'</td></tr>').join('');document.querySelectorAll('.stage').forEach((card,j)=>card.classList.toggle('active',j===i));document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode))}
function choose(id,update=true){if(!byId.has(id))return;current=byId.get(id);$('design').value=id;$('rung').max=current.stages.length-1;$('rung').value=current.stages.length-1;$('stages').innerHTML=current.stages.map((s,i)=>'<article class=stage data-stage="'+i+'" tabindex=0 role=button><h3>'+esc(s.name)+'</h3><img loading=lazy src="'+s.lines+'" alt="'+esc(s.name)+'"><p>'+esc(s.description)+'</p></article>').join('');document.querySelectorAll('.stage').forEach(el=>{const pick=()=>{$('rung').value=el.dataset.stage;render()};el.onclick=pick;el.onkeydown=e=>{if(e.key==='Enter')pick()}});document.querySelectorAll('.card').forEach(c=>c.classList.toggle('selected',c.dataset.case===id));if(update){try{const u=new URL(location.href);u.searchParams.set('design',id);u.hash='';history.replaceState(null,'',u.href)}catch{}}render();paintRatings()}
$('design').onchange=e=>choose(e.target.value);$('rung').oninput=render;$('previous').onclick=()=>choose(cases[(cases.indexOf(current)+cases.length-1)%cases.length].id);$('next').onclick=()=>choose(cases[(cases.indexOf(current)+1)%cases.length].id);document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});document.querySelectorAll('.card').forEach(el=>{const pick=()=>{choose(el.dataset.case);$('inspection').scrollIntoView()};el.onclick=pick;el.onkeydown=e=>{if(e.key==='Enter')pick()}});
function filter(){const family=$('family').value,q=$('search').value.toLowerCase();let n=0;document.querySelectorAll('.card').forEach(el=>{const c=byId.get(el.dataset.case);el.hidden=!!((family&&c.family!==family)||q&&!JSON.stringify([c.id,c.name,c.family,c.description]).toLowerCase().includes(q));if(!el.hidden)n++});$('shown').textContent=n+' / '+cases.length} $('family').onchange=filter;$('search').oninput=filter;
document.querySelectorAll('[data-rating]').forEach(b=>b.onclick=()=>{const r=review(current);ratings[current.id]={rating:Number(b.dataset.rating),note:r?.note||'',fingerprint:current.fingerprint};persist()});$('review-note').oninput=e=>{const r=review(current);ratings[current.id]={rating:r?.rating||0,note:e.target.value,fingerprint:current.fingerprint};try{localStorage.setItem(key,JSON.stringify(ratings))}catch{}};
$('export').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({schema:key,ratings},null,2)],{type:'application/json'}));a.href=url;a.download='gojo-lattice-interior-ratings.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('import').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(data.schema!==key||!data.ratings)throw Error('Unknown rating format');for(const[id,r]of Object.entries(data.ratings)){if(byId.has(id)&&r.fingerprint===byId.get(id).fingerprint&&Number.isInteger(r.rating)&&r.rating>=0&&r.rating<=5&&typeof r.note==='string')ratings[id]=r}persist()}catch(error){$('rating-status').textContent=error.message}e.target.value=''};
const initial=new URLSearchParams(location.search).get('design')||location.hash.slice(1);choose(byId.has(initial)?initial:cases[0].id,false);filter();
</script></main></body></html>
""";
        // The full diagnostic keeps every derived shape field. The browser
