    private static string ConstructionStrips(IReadOnlyList<Plate> plates) => Start("Interior lattice construction stages") +
        "<span class=eyebrow>Gojo / merge interiors and negotiate shared boundaries</span><h1>Make a cell by removing its dividers.</h1><nav><a href='gallery.html'>Inspect and rate</a><a href='overview.html'>All final fields</a></nav>" +
        string.Join("", plates.Select(p => $"<section><h2><a href='gallery.html?design={p.Id}'>{H(p.Id + " · " + p.Name)}</a></h2><p>{H(p.Description)}</p><div class=stages>" +
            string.Join("", p.Stages.Select(s => $"<article class=stage><h3>{H(s.Name)}</h3><img loading=lazy src='{s.Fill}' alt='{H(s.Name)}'><p>{H(s.Description)}</p><span class='badge {(s.Embedded ? "" : "bad")}'>{(s.Embedded ? "Exclusive partition" : "Unsettled proposal")}</span></article>")) + "</div></section>")) + "</main></body></html>";
    private static string OverviewSvg(IReadOnlyList<Plate> plates, string output)
    {
        const int columns = 8, w = 300, h = 270;
        var svg = new StringBuilder($"<svg xmlns='http://www.w3.org/2000/svg' width='{columns*w}' height='{100+(plates.Count+columns-1)/columns*h}'><rect width='100%' height='100%' fill='#EDEADF'/><text x='24' y='42' font-family='Georgia,serif' font-size='32' fill='#304C50'>Interior-first lattices · one hundred exclusive partitions</text><text x='25' y='75' font-family='sans-serif' font-size='15' fill='#63756A'>Shared atomic faces · repeated boundary deletion · negotiated ownership · selected display basis</text>");
        for (var i = 0; i < plates.Count; i++)
        {
            var p = plates[i]; var x = i % columns * w; var y = 100 + i / columns * h;
            var drawing = System.Xml.Linq.XElement.Parse(File.ReadAllText(Path.Combine(output, p.Id + "-cells.svg")));
            drawing.SetAttributeValue("x", x + 6); drawing.SetAttributeValue("y", y + 37); drawing.SetAttributeValue("width", w - 12); drawing.SetAttributeValue("height", h - 42);
            var title = p.Name.Length > 35 ? p.Name[..32] + "…" : p.Name;
            svg.Append($"<text x='{x+10}' y='{y+15}' font-family='Georgia,serif' font-size='14' fill='#304C50'>{H(p.Id + " · " + title)}</text><text x='{x+10}' y='{y+30}' font-family='sans-serif' font-size='10' fill='#63756A'>{H(p.Family)}</text>{drawing}");
        }
        return svg.Append("</svg>").ToString();
    }
    private static string Rules(object[] counterexamples)
    {
        var data = JsonSerializer.SerializeToElement(counterexamples, Json);
        return Start("What makes a bad lattice interior?") + """
<span class=eyebrow>Gojo / explicit rules for this experiment</span><h1>Judge the spaces as well as the lines.</h1><nav><a href='gallery.html'>Inspect the catalogue</a><a href='overview.html'>All 100 fields</a></nav>
<h2>Hard rejection rules</h2><p>Every actual atomic face has exactly one owner. Each merged interior is connected through shared edges, has one closed simple boundary, and is composed of valid convex atoms whose interiors do not overlap in the declared embedding. Shared contacts require actual shared edges and sites. The native packet retains the participating atoms, boundary darts, binding basis and rejected claims.</p>
<p>This is stronger than checking that two lines do not retrace. The coloured interiors must be a partition of the supplied atomic domain. Finite frontiers are retained; coverage of the entire plane is a separate claim.</p>
<div class=rules>
""" + string.Join("", data.EnumerateArray().Select(row => $"<article class=panel><h3>{H(row.GetProperty("id").GetString()! + " · " + row.GetProperty("name").GetString())}</h3><img src='{row.GetProperty("id").GetString()}.svg' alt='Rejected native partition example'><p>{row.GetProperty("blocked").GetInt32()} blocked witnesses; {row.GetProperty("open").GetInt32()} unresolved.</p><a href='{row.GetProperty("id").GetString()}.gojo.json.gz'>Actual counterexample packet</a></article>")) + """
</div><h2>Preferences that still need judgement</h2><p>Broad turns can define a new cell. Small repeated excursions that quickly return to the same heading can refine an old edge without establishing a new lattice shape. The shape reader retains both kinds of turning evidence; a many-pointed star is not rejected merely for alternating convex and reflex corners.</p>
<div class=table><table><thead><tr><th>Read</th><th>Why it helps</th><th>Limit</th></tr></thead><tbody><tr><td>Sides after straight collapse</td><td>Counts broad shape changes rather than arbitrary subdivisions</td><td>Side count alone does not distinguish a star from noise</td></tr><tr><td>Fine same-heading returns</td><td>Finds small teeth along a larger directional run</td><td>Chosen relative scale is an authored preference</td></tr><tr><td>Interior scale and shortest runs</td><td>Compares boundary detail with the region it bounds</td><td>Depends on the declared common-reach basis</td></tr><tr><td>Area / bounding box</td><td>Makes slender or widely reaching cells noticeable</td><td>A slanted grid can be excellent despite low occupancy</td></tr><tr><td>Atomic ownership and shared seams</td><td>Prevents filling two apparent rectangles over one another</td><td>Cannot establish universal aesthetic merit</td></tr></tbody></table></div>
<p>The gallery marks a boundary-detail cue when there are at least three fine same-heading returns and their fraction exceeds 35%. It does not convert this exploratory threshold into a hard geometry law. Human ratings and notes can help revise it.</p><h2>Seams are a two-sided question</h2><p>Shape-first cases retain neighbours' competing atomic claims. Each contested atom needs an explicit selected owner; the losing proposal remains blocked. The accepted ownership is checked again for connected cells and sound embedding. An accepted choice does not by itself prove a valid shape.</p><p class=note>No numeric carriers, bitmap segmentation, global pattern recognizer or hidden geometric join inference is used here. Formal counts and shape ratios are derived observation reads.</p></main></body></html>
""";
    }
}
